import gzip,pandas as pd
def meta(f):
    rows={}
    for l in gzip.open(f'studies/data/raw/{f}_series_matrix.txt.gz','rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith('!Sample_'):
            p=[x.strip('"') for x in l.rstrip('\n').split('\t')]
            k=p[0]; i=2
            while k in rows: k=p[0]+str(i); i+=1
            rows[k]=p[1:]
    return pd.DataFrame(rows)
pd.set_option('display.width',300,'display.max_colwidth',60,'display.max_rows',500)
m=meta('paper_2_GSE21618')
cols=[c for c in m.columns if m[c].nunique()>1 and 'supplementary' not in c and 'geo_acc' not in c]
print(m[['!Sample_geo_accession','!Sample_title']+[c for c in cols if 'charact' in c]].to_string())

